from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel
import stripe

router = APIRouter(prefix="/merchants")

class PayoutRequest(BaseModel):
    amount_cents: int
    currency: str = "usd"

@router.post("/{account_id}/payouts")
async def trigger_connected_payout(
    account_id: str,
    payload: PayoutRequest,
    user_accounts: AccountManager = Depends(get_account_manager),
    current_user: User = Depends(get_current_user)
):
    if not await user_accounts.is_account_authorized(user_id=current_user.id, account_id=account_id):
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Forbidden: user does not manage this Stripe account")

    try:
        payout = stripe.Payout.create(
            amount=payload.amount_cents,
            currency=payload.currency,
            stripe_account=account_id
        )
        return {
            "payout_id": payout.id,
            "account_id": account_id,
            "status": payout.status,
            "amount": payout.amount
        }
    except stripe.error.StripeError as e:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(e))
